from conan import ConanFile
from conan.tools.files import get
from conan.tools.cmake import CMake, cmake_layout

class PigpioConan(ConanFile):
    name = "pigpio"
    version = "1.0"
    package_type = "static-library"
    settings = "os", "compiler", "build_type", "arch"
    generators = "CMakeToolchain"

    def source(self):
        get(self, "https://github.com/joan2937/pigpio/archive/refs/tags/v79.tar.gz", strip_root=True)

    def layout(self):
        cmake_layout(self)

    def build(self):
        cmake = CMake(self)
        cmake.configure()
        cmake.build()

    def package(self):
        cmake = CMake(self)
        cmake.install()

    def package_info(self):
        # Only local compiled library files generated by pigpio
        self.cpp_info.libs = ["pigpio"]
        # System C libraries provided by Linux OS
        self.cpp_info.system_libs = ["pthread", "rt"]